from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x, grid[y][x]))
                for dy, dx in ((1,0), (-1,0), (0,1), (0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append(comp)
    proto = max(comps, key=len)
    r0, r1 = min(r for r, c, v in proto), max(r for r, c, v in proto)
    c0, c1 = min(c for r, c, v in proto), max(c for r, c, v in proto)
    cr, cc = (r0 + r1) // 2, (c0 + c1) // 2
    out = [row[:] for row in grid]
    for comp in comps:
        if len(comp) != 1 or comp is proto:
            continue
        mr, mc = comp[0][:2]
        for r, c, v in proto:
            rr, col = mr + r - cr, mc + c - cc
            if 0 <= rr < h and 0 <= col < w:
                out[rr][col] = v
    return out


